import{_ as t,c as i,o as l,a5 as a}from"./chunks/framework.BLFC1wTn.js";const x=JSON.parse('{"title":"CSS","description":"","frontmatter":{},"headers":[],"relativePath":"pages/interview/css/index.md","filePath":"pages/interview/css/index.md","lastUpdated":1727883585000}'),e={name:"pages/interview/css/index.md"},n=a('<h1 id="css" tabindex="-1">CSS <a class="header-anchor" href="#css" aria-label="Permalink to &quot;CSS&quot;">​</a></h1><h2 id="选择器及其优先级" tabindex="-1">选择器及其优先级 <a class="header-anchor" href="#选择器及其优先级" aria-label="Permalink to &quot;选择器及其优先级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选择器</th><th style="text-align:center;">格式</th><th style="text-align:right;">优先级权重</th></tr></thead><tbody><tr><td>id选择器</td><td style="text-align:center;">#id</td><td style="text-align:right;">100</td></tr><tr><td>类选择器</td><td style="text-align:center;">#classname</td><td style="text-align:right;">10</td></tr><tr><td>属性选择器</td><td style="text-align:center;">a[ref=&quot;xxx&quot;]</td><td style="text-align:right;">10</td></tr><tr><td>伪类选择器</td><td style="text-align:center;">li:last-child</td><td style="text-align:right;">10</td></tr><tr><td>标签选择器</td><td style="text-align:center;">div</td><td style="text-align:right;">1</td></tr><tr><td>伪元素选择器</td><td style="text-align:center;">li:after</td><td style="text-align:right;">1</td></tr><tr><td>相邻兄弟选择器</td><td style="text-align:center;">div+p</td><td style="text-align:right;">0</td></tr><tr><td>子代选择器</td><td style="text-align:center;">ul&gt;li</td><td style="text-align:right;">0</td></tr><tr><td>后代选择器</td><td style="text-align:center;">li a</td><td style="text-align:right;">0</td></tr><tr><td>通配符选择器</td><td style="text-align:center;">*</td><td style="text-align:right;">0</td></tr></tbody></table><p>!important声明的样式优先级最高，内联次之；<br> 优先级相同，最后出现的样式生效<br> 继承得到的样式优先级最低<br> 通用选择器<br> 样式表的来源：内联样式 -&gt; 内部样式 -&gt; 外部样式 -&gt; 浏览器用户自定义样式 -&gt; 浏览器默认样式</p><h2 id="css可继承与不可继承的属性有哪些" tabindex="-1">CSS可继承与不可继承的属性有哪些 <a class="header-anchor" href="#css可继承与不可继承的属性有哪些" aria-label="Permalink to &quot;CSS可继承与不可继承的属性有哪些&quot;">​</a></h2><p><strong>不可继承</strong></p><ol><li>display 规定元素应该生成的框的类型</li><li>vertical-align：垂直文本对齐</li><li>text-decoration:规定添加到文本的装饰</li><li>text-shadow：文本的阴影效果</li><li>white-space：空白符的处理</li><li>unicode-bidi：设置文本的方向</li><li>width、height、margin、border、padding</li><li>background、background-color、background-image、background-repeat、background-position、background-repeat、background-position、background-attachment</li><li>floa、clear、position、top、right、bottom、left、min-width、minheight、max-width、max-height、overflow、clip、z-index</li></ol><p><strong>可继承</strong></p><ol><li>font-family、font-weight、font-size、font-style</li><li>text-indent、text-align、line-height、letter-spacing、word-spacing、color</li><li>visibility、list-style、cursor</li></ol><h2 id="display属性有哪些值" tabindex="-1">display属性有哪些值 <a class="header-anchor" href="#display属性有哪些值" aria-label="Permalink to &quot;display属性有哪些值&quot;">​</a></h2><ul><li>block：块级元素，独占一行，宽度默认是父元素宽度，高度默认是内容高度</li><li>inline：行内元素，不独占一行，宽度默认是内容宽度，高度默认是内容高度</li><li>inline-block：行内块元素，既可以设置宽度和高度，又可以设置margin和padding，不独占一行</li><li>none：隐藏元素，不占据任何空间</li><li>table-cell：单元格元素，可以设置宽度和高度，不独占一行</li><li>table-row：行元素，不独占一行</li><li>table-caption：标题元素，不独占一行</li><li>list-item：列表项元素，不独占一行</li></ul><h2 id="行内元素和块级元素有什么区别" tabindex="-1">行内元素和块级元素有什么区别 <a class="header-anchor" href="#行内元素和块级元素有什么区别" aria-label="Permalink to &quot;行内元素和块级元素有什么区别&quot;">​</a></h2><ol><li>块级元素：独占一行，宽度默认是父元素宽度，高度默认是内容高度，可以设置margin和padding，换行自动</li><li>行内元素：不独占一行，宽度默认是内容宽度，高度默认是内容高度，可以设置水平方向的margin和padding，不能设置垂直方向的margin和padding，不自动换行</li><li>行内块元素：既可以设置宽度和高度，又可以设置margin和padding，不独占一行</li></ol><h2 id="隐藏元素的方法" tabindex="-1">隐藏元素的方法 <a class="header-anchor" href="#隐藏元素的方法" aria-label="Permalink to &quot;隐藏元素的方法&quot;">​</a></h2><ol><li>display:none：将元素的display属性设置为none，元素将不可见，不占据空间，不响应绑定的监听事件</li><li>visibility:hidden：将元素的visibility属性设置为hidden，元素仍然占据空间，只是不可见，不响应绑定的监听事件</li><li>opacity:0：将元素的opacity属性设置为0，元素仍然占据空间，只是透明度为0，响应绑定的监听事件</li><li>postion:absolute;将元素的position属性设置为absolute,再移除可视区域内，元素仍然占据空间，只是不可见</li><li>z-index:-999：将元素的z-index属性设置为负值，使其他元素遮盖该元素</li><li>clip/clip-path：使用元素裁剪的⽅法来实现元素的隐藏，这种方法下，元素仍在页面中占据位置，但是不会响应绑定的监听事件。</li><li>transform:scale(0);将元素的transform属性设置为缩放0，元素仍然占据空间，只是缩放为0，不会响应绑定的监听事件。</li></ol><h2 id="link和-import的区别" tabindex="-1">link和@import的区别 <a class="header-anchor" href="#link和-import的区别" aria-label="Permalink to &quot;link和@import的区别&quot;">​</a></h2><ul><li>link是HTML标签，除了加载CSS外，还可以定义RSS，@import是CSS的语法，两者都可以用来导入样式表。</li><li>link引用CSS时，在页面载入的同时加载，@import需要页面网页完全载入以后加载</li><li>link是HTML标签，无兼容问题，@import是CSS语法，不兼容IE5以下</li><li>link支持使用JS控制DOM改变样式，@import不支持</li></ul><h2 id="transition和animation的区别" tabindex="-1">transition和animation的区别 <a class="header-anchor" href="#transition和animation的区别" aria-label="Permalink to &quot;transition和animation的区别&quot;">​</a></h2><ul><li>transition是过渡属性，可以实现元素的过渡效果，比如颜色的变化、宽度的变化等。它的实现需要触发一个事件，比如鼠标移入移出、鼠标悬停等才执行，可以设置一个开始帧，一个结束帧</li><li>animation是动画属性，可以实现更复杂的动画效果，比如淡入淡出、旋转、缩放等。它的实现不需要触发事件，可以设置多个关键帧，可以设置动画的时长、次数、方向、播放方式等。</li></ul><h2 id="伪元素和伪类的区别和作用" tabindex="-1">伪元素和伪类的区别和作用 <a class="header-anchor" href="#伪元素和伪类的区别和作用" aria-label="Permalink to &quot;伪元素和伪类的区别和作用&quot;">​</a></h2><ul><li>伪元素：是CSS3新增的一种选择器，用来创建一些不在文档树中的元素，比如：::before、::after。</li><li>伪类：是CSS3新增的一种选择器，用来向某些选择器添加特殊的效果，比如：:hover、:active、:focus等。</li></ul><h2 id="盒模型" tabindex="-1">盒模型 <a class="header-anchor" href="#盒模型" aria-label="Permalink to &quot;盒模型&quot;">​</a></h2><ul><li>标准盒模型：宽度=内容宽度，高度=内容高度</li><li>怪异盒模型：宽度=内容宽度+左右内边距+左右边框，高度=内容高度+上下内边距+上下边框</li><li>通过box-sizing属性设置盒模型，默认值为content-box，即标准盒模型，border-box为怪异盒模型(IE盒子)</li></ul><h2 id="为什么有时候用translate来改变位置而不用定位" tabindex="-1">为什么有时候用translate来改变位置而不用定位 <a class="header-anchor" href="#为什么有时候用translate来改变位置而不用定位" aria-label="Permalink to &quot;为什么有时候用translate来改变位置而不用定位&quot;">​</a></h2>',24),r=[n];function d(o,s,h,c,g,p){return l(),i("div",null,r)}const u=t(e,[["render",d]]);export{x as __pageData,u as default};
